import {applyEmergencySurcharges} from './emergency-surcharges.js';
import {addSurcharge} from './line-adjustments.js';
import {recordCostBasis} from './workflow-core.js';
export function setupWorkflowTools(api){
 const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>Number(n).toLocaleString('ko-KR');
 const options=(items,value)=>Object.entries(items).map(([k,v])=>`<option value="${k}" ${k===value?'selected':''}>${v}</option>`).join('');
 const fields={labor:'노무비',material:'재료비',expense:'경비',other:'기타'};
 document.body.insertAdjacentHTML('beforeend','<dialog id="workflowDialog"><div class="dialog-head"><h2 id="workflowTitle"></h2><button class="icon-btn" data-close="workflowDialog">×</button></div><div class="mapped-body" id="workflowBody"></div><div class="dialog-actions"><span id="workflowMessage" role="status"></span><button class="button primary" id="workflowApply">적용</button></div></dialog>');
 const open=(title,html,apply,label='적용')=>{$('workflowTitle').textContent=title;$('workflowBody').innerHTML=html;$('workflowMessage').textContent='';$('workflowApply').textContent=label;$('workflowApply').disabled=false;$('workflowApply').onclick=()=>{try{apply();}catch(e){$('workflowMessage').textContent=e.message;}};$('workflowDialog').showModal();};
 const save=p=>{api.replaceProject(p);$('workflowDialog').close();};
 function surcharge(id=api.getSelected()){
  const p=api.getProject(),selected=p.lines.find(l=>l.id===id);if(!selected){api.toast('할증을 넣을 공종 또는 공구의 행을 먼저 선택하세요.');return;}
  const s=selected.surcharge||{};
  if(s.kpAllowance){open('KP 이탈방지압륜 가산',`<p>지정한 KP 품의 비목별 금액에 적용합니다. 작업 본수는 바꾸지 않습니다.</p><p>${esc(s.kpAllowance.identities.map(x=>x.name+' '+x.spec).join(', '))}</p><div class="work-fields"><label>대상 본수<input id="wfKpQuantity" type="number" min="0" step="any" value="${s.kpAllowance.quantity}"></label><label>가산율 %<input id="wfPercent" type="number" min="0" max="30" step="any" value="${selected.qty}"></label><label>적용 근거<input id="wfReason" value="${esc(s.kpAllowance.reason||'')}"></label></div>`,()=>{const percent=Number($('wfPercent').value),quantity=Number($('wfKpQuantity').value),reason=$('wfReason').value.trim();if(!Number.isFinite(percent)||percent<0||percent>30||!Number.isFinite(quantity)||quantity<=0||!reason)throw Error('30% 이내 가산율·대상 본수·근거를 확인하세요.');const next=structuredClone(p),row=next.lines.find(x=>x.id===id);row.qty=percent;row.surcharge.kpAllowance={...row.surcharge.kpAllowance,quantity,totalQuantity:next.lines.filter(x=>row.surcharge.sourceIds.includes(x.id)).reduce((n,x)=>n+Number(x.qty),0),reason};row.spec='KP 대상 '+quantity+'본';row.note=reason;save(next);});return;}
  open('공종 · 공구 할증',`<p>선택 범위의 끝에 할증행을 넣습니다. 수량·단가·낙찰 변경 시 자동 재계산합니다.</p><div class="work-fields"><label>품명<input id="wfName" value="${esc(s.scope?selected.name:'기타할증')}"></label><label>범위<select id="wfScope">${options({group:'현재 L1 공종',section:'현재 L2 공구',selected:'선택한 기준 행'},s.scope||'group')}</select></label><label>기준 비목<select id="wfBasis">${options({...fields,total:'합계'},s.basis||'labor')}</select></label><label>계상 비목<select id="wfTarget">${options(fields,s.target||'labor')}</select></label><label>할증률 %<input id="wfPercent" type="number" min="0" max="1000" step="any" value="${s.scope?selected.qty:30}"></label><label class="check"><input id="wfInclude" type="checkbox" ${(s.includeSurcharges??true)?'checked':''}>앞선 할증도 기준에 포함</label></div><details><summary>직접 선택할 기준 행</summary><div class="work-table">${p.lines.filter(l=>!l.level&&!l.exclude&&l.id!==id&&l.bucket==='direct').map(l=>`<label class="check"><input type="checkbox" data-wf-source="${l.id}" ${s.sourceIds?.includes(l.id)?'checked':''}>${esc(l.group+' / '+l.name+' '+l.spec)}</label>`).join('')}</div></details>`,()=>save(addSurcharge(p,id,{name:$('wfName').value,scope:$('wfScope').value,basis:$('wfBasis').value,target:$('wfTarget').value,percent:Number($('wfPercent').value),includeSurcharges:$('wfInclude').checked,sourceIds:[...$('workflowBody').querySelectorAll('[data-wf-source]:checked')].map(x=>x.dataset.wfSource)})));
 }
 function deduction(){open('감액 항목 추가','<div class="work-fields"><label>품명<input id="wfName" value="분담금 감액"></label><label>감액 금액(양수 입력)<input id="wfAmount" type="number" min="1" step="1"></label><label>계상 구분<select id="wfBucket">'+options({fees:'수수료·부담금',government:'관급자재',direct:'직접공사비',waste:'폐기물'},'fees')+'</select></label><label>계상 비목<select id="wfTarget">'+options(fields,'expense')+'</select></label><label>감액 근거<input id="wfReason" placeholder="예: 기존 분담금 차감"></label></div>',()=>{const value=Number($('wfAmount').value),reason=$('wfReason').value.trim();if(!Number.isFinite(value)||value<=0||!reason)throw Error('금액과 감액 근거를 입력하세요.');const p=structuredClone(api.getProject()),key=$('wfTarget').value,name=$('wfName').value;p.lines.push({id:crypto.randomUUID(),group:'감액',name,spec:'',unit:'식',qty:-1,factor:1,bucket:$('wfBucket').value,status:'confirmed',deduction:{reason},rate:{name,source:'직접 감액',code:'DEDUCTION',labor:0,material:0,expense:0,other:0,[key]:value,total:value},note:reason});p.ratesReviewed=false;save(p);});}
 function contractor(){api.exportFile();}
 function basis(){const p=api.getProject(),b=p.costBasis||{};open('공사 기준 · 요율 이력',`<p>기준일과 표 이름, 현재 요율·가격 DB 정보를 공사 파일에 함께 보관합니다. 기존 공사의 단가나 요율을 자동 변경하지 않습니다.</p><div class="work-fields"><label>적용 기준일<input id="wfDate" type="date" value="${esc(b.date||new Date().toLocaleDateString('sv-SE'))}"></label><label>제비율표 이름·버전<input id="wfSource" value="${esc(b.source||'')}" placeholder="예: 2026.04.13 토목 제비율표"></label><label>긴급보수 도급 한도(0=표시 안 함)<input id="wfLimit" type="number" min="0" value="${p.contractLimit??(/긴급|보수/.test(p.title)?10000000:0)}"></label></div><p>단가 기준: ${esc(p.resourcePriceLibrary?.name||'현재 저장된 품목별 단가')}</p><div class="work-table"><table><thead><tr><th>기준일</th><th>표 이름</th><th>저장 당시 도급액</th></tr></thead><tbody>${(p.costBasisHistory||[]).map(x=>`<tr><td>${esc(x.date)}</td><td>${esc(x.source)}</td><td>${money(x.contract)}</td></tr>`).join('')}</tbody></table></div>`,()=>{const limit=Number($('wfLimit').value);if(!Number.isFinite(limit)||limit<0)throw Error('도급 한도를 확인하세요.');save(recordCostBasis({...p,contractLimit:limit},{date:$('wfDate').value,source:$('wfSource').value},api.getLibraries()));},'기준 이력 저장');}
 for(const [id,label,run] of [['emergencySurcharge','긴급보수 기본 할증',()=>{const result=applyEmergencySurcharges(api.getProject());if(result.added)api.replaceProject(result.project);api.toast(`할증 ${result.added}개 추가 · 기존 ${result.kept}개 유지. 토공·포장공 50%, 배관공 30% (노무비 기준)`);}],['documentSurcharge','공종·공구 할증',()=>surcharge()],['deductionTool','감액 항목',deduction],['costBasisTool','공사 기준·요율 이력',basis]]){const b=document.createElement('button');b.id=id;b.className='button';b.textContent=label;b.onclick=run;$('estToolsDialog').querySelector('.tool-menu').append(b);}
 $('contractorExport').onclick=contractor;
 document.addEventListener('click',e=>{const b=e.target.closest('[data-adjustment-edit]');if(b)surcharge(b.dataset.adjustmentEdit);});
 return {surcharge,contractor};
}
